    # First pass to find the minimum imbalance
    for char in s:
        if char == '(':
            imbalance += 1
        else:
            imbalance -= 1
        min_imbalance = min(min_imbalance, imbalance)

    # If the sequence is already balanced, return "possible"
    if imbalance == 0 and min_imbalance >= 0:
        return "possible"

    # If the sequence cannot be fixed by a single inversion, return "impossible"
    if imbalance != 0 or min_imbalance > -1:
